  const li=()=>{const i=LANGS.indexOf(typeof getLang==='function'?getLang():'ru');return i<0?1:i};
  function name(code,lang){const i=lang?Math.max(0,LANGS.indexOf(lang)):li();const n=N[code];return n?(n[i]||n[1]||code):code}
  function region(code,lang){const i=lang?Math.max(0,LANGS.indexOf(lang)):li();if(G[code])return G[code][i]||G[code][1];const h=HOME[code];return h&&R[h]?(R[h][i]||R[h][1]):''}
  function flagCode(code){return code==='EUR'?'EU':(HOME[code]||null)}
  window.STCurrency={name,region,flagCode,home:HOME};
  if(typeof CURRENCY_COUNTRIES==='object')for(const c in HOME){if(HOME[c]&&c!=='EUR')CURRENCY_COUNTRIES[c]=HOME[c]}
  if(typeof CURRENCIES==='object')CURRENCIES.forEach(c=>{if(!c.name||c.name===c.code)c.name=name(c.code,'en')});
